/**
 * load-projects.js — homepage script.
 * Fetches site/data/{title,projects}.json (generated by scripts/build.py)
 * and renders the hero + project card grid. No hand-editing of HTML needed
 * to add a project — just add a YAML file and rebuild.
 */
(function () {
  async function fetchJSON(path) {
    const res = await fetch(path);
    if (!res.ok) throw new Error('Failed to fetch ' + path);
    return res.json();
  }

  function el(tag, className, html) {
    const e = document.createElement(tag);
    if (className) e.className = className;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }

  function renderHero(title) {
    const nameEl = document.querySelector('[data-hero-name]');
    const taglineEl = document.querySelector('[data-hero-tagline]');
    const ledeEl = document.querySelector('[data-hero-lede]');
    const linksEl = document.querySelector('[data-hero-links]');
    if (nameEl) nameEl.textContent = title.name;
    if (taglineEl) taglineEl.textContent = title.tagline;
    if (ledeEl) ledeEl.textContent = title.location ? `Based in ${title.location}.` : '';
    if (linksEl) {
      linksEl.innerHTML = '';
      const entries = [
        ['Email', 'mailto:' + title.email],
        ['GitHub', title.links && title.links.github],
        ['LinkedIn', title.links && title.links.linkedin],
        ['Resume (PDF)', title.resume_pdf],
      ];
      entries.forEach(([label, href]) => {
        if (!href) return;
        const a = el('a', null, label);
        a.href = href;
        linksEl.appendChild(a);
      });
    }
    document.title = `${title.name} — ${title.tagline}`;
  }

  function renderCard(project) {
    const card = el('article', 'project-card');

    const thumb = el('div', 'thumb');
    if (project.main_media && project.main_media.type !== 'video') {
      const img = el('img');
      img.src = project.main_media.src;
      img.alt = project.main_media.title || project.title;
      img.loading = 'lazy';
      thumb.appendChild(img);
    }
    card.appendChild(thumb);

    const body = el('div', 'body');
    body.appendChild(el('h3', null, project.title));
    if (project.dates) body.appendChild(el('div', 'meta', project.dates));
    body.appendChild(el('p', null, project.short_description));

    if (project.tags && project.tags.length) {
      const tagsWrap = el('div', 'tags');
      project.tags.forEach((t) => tagsWrap.appendChild(el('span', 'tag', t)));
      body.appendChild(tagsWrap);
    }
    card.appendChild(body);

    const link = el('a');
    link.href = `project.html?slug=${encodeURIComponent(project.slug)}`;
    link.style.display = 'contents';
    link.setAttribute('aria-label', `View project: ${project.title}`);
    link.appendChild(card);
    return link;
  }

  async function main() {
    const grid = document.querySelector('[data-project-grid]');
    try {
      const [title, projects] = await Promise.all([
        fetchJSON('data/title.json'),
        fetchJSON('data/projects.json'),
      ]);
      renderHero(title);
      if (grid) {
        grid.innerHTML = '';
        projects.forEach((p) => grid.appendChild(renderCard(p)));
      }
    } catch (err) {
      console.error(err);
      if (grid) grid.innerHTML = '<p style="color:#7C8894">Could not load project data.</p>';
    }
  }

  main();
})();
